// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 balance, uint256 amount) public {
        // keep the deal in a sane range so the fuzzed balance is admissible
        balance = bound(balance, 0, type(uint128).max);
        amount = bound(amount, 0, type(uint256).max);
        vm.deal(address(c), balance);

        // msg.sender of this call is the test contract, which is c's owner
        // (owner = payable(msg.sender) at deployment in setUp).
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: an over-withdrawal (amount > c's balance) can never
        // succeed — the reference reverts because its transfer exceeds the
        // balance. The mutant's empty withdraw() succeeds for every input.
        assertTrue(amount <= balance || !ok);
    }
}
